


export type NextAction = { "action_type": string; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Request body fields to send to POST /v1/merchant-account-sessions when action_type is create_merchant_account_session. */ "merchant_account_session"?: { /** Recommended verification collection breadth. */ "collection_strategy"?: "upfront" | "incremental" | (string & {}); /** Resolver-recommended component to send to POST /v1/merchant-account-sessions. */ "component": "account_onboarding" | "account_management" | "payouts" | "balances" | "tax_documents" | "notification_banner" | (string & {}); /** Recommended future-requirement collection behavior. */ "future_requirements"?: "omit" | "include" | (string & {}); }; "reason_code"?: string; "reason_message"?: string; "required_fields"?: Array<string>; /** API key scope required to call the public endpoint in url, when the action points at another Flint API endpoint. */ "required_scope"?: string; "requires_human_confirmation"?: boolean; /** Format: int32. */ "suggested_delay_milliseconds"?: number; /** Public endpoint or launch URL for this remediation action, when applicable. */ "url"?: string; };
